["{
  "record": {
    "type": "object",
    "$defs": {
      "Address": {
        "type": "object",
        "$defs": {
          "city": {
            "type": "string",
            "title": "City"
          },
          "postcode": {
            "anyOf": [{
              "type": "string",
              "title": "Postcode"
            }, {
              "type": "null",
              "title": "None"
            }]
          },
          "street": {
            "type": "string",
            "title": "Street"
          },
          "required": [
            "street",
            "city",
            "postcode"
          ],
          "title": "Address"
        },
        "Contact": {
          "type": "object",
          "$defs": {
            "email": {
              "type": "string",
              "title": "Email"
            },
            "phone": {
              "anyOf": [{
                "type": "string",
                "title": "Phone"
              }, {
                "type": "null",
                "title": "None"
